<section class="page-title"><div><p class="eyebrow">MON APPRENTISSAGE</p><h1>Mes formations</h1><p>Retrouvez uniquement les parcours auxquels vous êtes réellement inscrit.</p></div><a class="btn secondary" href="/catalogue">Explorer le catalogue</a></section>
<?php if(!$courses): ?><section class="panel my-courses-empty"><span>▤</span><h2>Aucune formation active</h2><p>Après votre inscription et l’activation de votre compte, votre formation apparaîtra ici.</p><a class="btn primary" href="/formations">Découvrir les formations</a></section><?php else: ?><div class="my-courses-grid"><?php foreach($courses as $course): ?><article class="panel my-course-card"><div class="my-course-cover <?= htmlspecialchars($course['tone']??'indigo') ?>"><?php if(!empty($course['thumbnail'])): ?><img src="<?= htmlspecialchars($course['thumbnail']) ?>" alt="<?= htmlspecialchars($course['title']) ?>"><?php else: ?><span>IF</span><small><?= htmlspecialchars($course['category']) ?></small><?php endif ?><b><?= $course['status']==='completed'?'TERMINÉE':'EN COURS' ?></b></div><div class="my-course-content"><small><?= htmlspecialchars($course['category']) ?></small><h2><?= htmlspecialchars($course['title']) ?></h2><p>Par <?= htmlspecialchars($course['teacher']?:'Équipe IFMAP') ?></p><div class="course-numbers"><span><strong><?= (int)$course['modules'] ?></strong> sections</span><span><strong><?= (int)$course['completed_lessons'] ?>/<?= (int)$course['lessons'] ?></strong> leçons</span><span><strong><?= htmlspecialchars($course['duration_label']) ?></strong> durée</span></div><div class="progress-row"><div class="progress"><span style="width:<?= min(100,(int)$course['progress']) ?>%"></span></div><b><?= (int)$course['progress'] ?>%</b></div><footer><span>Inscrit le <?= date('d/m/Y',strtotime($course['enrolled_at'])) ?></span><div><?php if(!empty($course['certificate_id'])): ?><a class="btn secondary" href="/academie/diplome?id=<?= (int)$course['certificate_id'] ?>">Diplôme</a><?php endif ?><a class="btn primary" href="/academie/formation?course=<?= (int)$course['id'] ?>"><?= (int)$course['progress']>0?'Continuer':'Commencer' ?> →</a></div></footer></div></article><?php endforeach ?></div><?php endif ?>
<style>.my-courses-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.my-course-card{overflow:hidden}.my-course-cover{height:150px;position:relative;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;background:linear-gradient(135deg,#27205f,#6658e8)}.my-course-cover img{width:100%;height:100%;object-fit:cover}.my-course-cover>span{font:800 35px Manrope}.my-course-cover>small{opacity:.8}.my-course-cover>b{position:absolute;top:12px;left:12px;border-radius:20px;background:#fff;color:var(--primary);padding:5px 8px;font-size:8px}.my-course-content{padding:20px}.my-course-content>small{color:var(--primary);font-size:8px;font-weight:800;letter-spacing:1px}.my-course-content h2{font-size:17px;margin:7px 0}.my-course-content>p{color:var(--muted);font-size:10px}.course-numbers{display:flex;gap:18px;border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:13px 0;margin:14px 0}.course-numbers span{display:flex;flex-direction:column;color:var(--muted);font-size:8px}.course-numbers strong{color:var(--ink);font-size:11px}.my-course-content footer{display:flex;align-items:center;justify-content:space-between;margin-top:18px}.my-course-content footer>span{font-size:8px;color:var(--muted)}.my-course-content footer>div{display:flex;gap:7px}.my-courses-empty{text-align:center;padding:70px 20px}.my-courses-empty>span{font-size:40px;color:var(--primary)}.my-courses-empty p{color:var(--muted)}@media(max-width:800px){.my-courses-grid{grid-template-columns:1fr}.my-course-content footer{align-items:flex-start;gap:12px;flex-direction:column}}</style>
